public boolean maybeDequeueInputBuffer(DecoderInputBuffer inputBuffer){
  if (inputStreamEnded) {
    return false;
  }
  if (inputBufferIndex < 0) {
    try {
      inputBufferIndex = mediaCodec.dequeueInputBuffer(0);
      if (inputBufferIndex < 0) {
        return false;
      }
      inputBuffer.data = mediaCodec.getInputBuffer(inputBufferIndex);
      if (inputBuffer.data == null) {
        inputBufferIndex = -1;
        return false;
      }
      inputBuffer.clear();
    } catch (IllegalStateException e) {
      inputBufferIndex = -1;
      return false;
    }
  }
  checkNotNull(inputBuffer.data);
  return true;
}
